create extension if not exists pgcrypto;
create type public.app_role as enum ('depo', 'sube', 'yonetici');
create type public.order_status as enum ('bekliyor', 'hazirlaniyor', 'sevk_edildi', 'teslim_alindi', 'iptal');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role public.app_role not null default 'sube', branch_name text, active boolean not null default true, created_at timestamptz not null default now());
create table public.branches (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), name text not null unique, category text not null default 'Genel', unit text not null default 'adet', minimum_quantity numeric(12,3) not null default 0 check (minimum_quantity >= 0), active boolean not null default true, created_at timestamptz not null default now());
create table public.stock_batches (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), location_type text not null check (location_type in ('depo','sube')), branch_id uuid references public.branches(id), expiry_date date not null, quantity numeric(12,3) not null default 0 check (quantity >= 0), received_at timestamptz not null default now(), updated_at timestamptz not null default now(), check ((location_type = 'depo' and branch_id is null) or (location_type = 'sube' and branch_id is not null)));
create table public.orders (id uuid primary key default gen_random_uuid(), order_number bigint generated by default as identity unique, branch_id uuid not null references public.branches(id), created_by uuid references auth.users(id), status public.order_status not null default 'bekliyor', note text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_lines (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid not null references public.products(id), requested_quantity numeric(12,3) not null check (requested_quantity > 0), dispatched_quantity numeric(12,3) not null default 0 check (dispatched_quantity >= 0 and dispatched_quantity <= requested_quantity));
create table public.dispatches (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), created_by uuid references auth.users(id), dispatched_at timestamptz not null default now(), received_at timestamptz, received_by uuid references auth.users(id), note text not null default '');
create table public.dispatch_lines (id uuid primary key default gen_random_uuid(), dispatch_id uuid not null references public.dispatches(id) on delete cascade, order_line_id uuid not null references public.order_lines(id), stock_batch_id uuid not null references public.stock_batches(id), quantity numeric(12,3) not null check (quantity > 0));
create table public.stock_movements (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), stock_batch_id uuid references public.stock_batches(id), movement_type text not null check (movement_type in ('giris','sevkiyat','iade','duzeltme','fire')), quantity_delta numeric(12,3) not null check (quantity_delta <> 0), reference_type text, reference_id uuid, performed_by uuid references auth.users(id), created_at timestamptz not null default now(), note text not null default '');
create table public.purchase_requests (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), requested_quantity numeric(12,3) not null check (requested_quantity > 0), status text not null default 'taslak' check (status in ('taslak','gonderildi','karsilandi','iptal')), created_by uuid references auth.users(id), created_at timestamptz not null default now(), note text not null default '');
create index stock_batches_product_expiry_idx on public.stock_batches(product_id, expiry_date);
create index orders_status_created_idx on public.orders(status, created_at desc);
create index stock_movements_created_idx on public.stock_movements(created_at desc);
alter table public.profiles enable row level security;
alter table public.branches enable row level security;
alter table public.products enable row level security;
alter table public.stock_batches enable row level security;
alter table public.orders enable row level security;
alter table public.order_lines enable row level security;
alter table public.dispatches enable row level security;
alter table public.dispatch_lines enable row level security;
alter table public.stock_movements enable row level security;
alter table public.purchase_requests enable row level security;
-- Before production: add and test role-based RLS policies plus a transaction-based
-- server-side dispatch RPC with row locks. Do not decrement stock from the client.
